// Venue directory (Singapore). Compiled from venue websites, ActiveSG, onePA, and the venue
// round-ups by TheSmartLocal (updated 2026-06-18) and SassyMama (updated 2026-09-03), checked 2026-10-02;
// private paid courts added 2026-10-03 (mostly from official sites).
// Only venues with a sourced address; venues where sources conflict or only one blog mentions them are left out.
// Prices and hours change; the page says to check the venue's own notice. The region is our own
// mapping of the address to a URA region.
// Fields:
//   id        alphanumeric id used in URLs (#meetup?venue=<id>)
//   name      venue name
//   city      region; the directory groups by it, and array order is region order
//   address   address (for the map link)
//   setting   'indoor' | 'sheltered' | 'outdoor'; use an array when there are both, e.g. ['sheltered', 'outdoor']
//   courts    number of pickleball courts (number; leave out if unsure)
//   price     for the filter: lowest non-member hourly court fee in S$ (0 = free), read off fee; left out when fee has no number
//   operator  for the filter: 'public' (ActiveSG, CCs, schools, free HDB courts) | 'private' | 'club' (members' club)
//   fee       price, one sentence (SGD)
//   hours     opening hours, one sentence
//   booking   how to book: { type: 'phone' | 'whatsapp' | 'line' | 'url', value, label? }
//   note      note (optional)
//   source    data source (not shown; for checking)

const ACTIVESG = { type: 'url', value: 'https://activesg.gov.sg', label: 'Book on ActiveSG' };
const ONEPA = { type: 'url', value: 'https://www.onepa.gov.sg/facilities', label: 'Book on onePA' };
const PLAY_PICKLE = { type: 'url', value: 'https://app.courtreserve.com/online/publicbookings/13455' };
const ACTIVESG_FEE = 'Citizens / PR about S$3.50–9.50/hr (indoor cheaper, peak dearer)';
const ACTIVESG_NOTE = '1 hour per booking, max 2 slots a day. Peak slots go by ballot 14 days ahead; other slots open at noon 12 days ahead.';
const CC_NOTE = 'Shared badminton courts at the community centre; usually bring your own net. Some only rent the whole hall.';
const FREE_NOTE = 'Public HDB court, no booking needed; usually bring your own net.';
const SCHOOL_NOTE = 'School hall (opened to the public via ActiveSG), mostly evenings and weekends; popular slots go by ballot.';
const CHECK = 'Only one or unofficial sources; check before you go.';
const school = (id, name, city, address) => ({ id, country: 'sg', name, city, address, price: 3.5, operator: 'public', setting: 'indoor', fee: ACTIVESG_FEE, booking: [ACTIVESG], note: SCHOOL_NOTE, source: 'activesg.gov.sg pickleball venue list; moe.edu.sg school contact' });

